using System.Text.Json;
using VisionFramework;
using VisionPlugins.BranchModule;
using VisionPluginContracts;
static class Program {
 static int checks;static void Check(bool condition,string message){if(!condition)throw new Exception(message);checks++;}
 [STAThread]static int Main(){try{_ = new System.Windows.Application();Run();Console.WriteLine($"PASS {checks} Branch production checks; original runtime not executed");return 0;}catch(Exception error){Console.Error.WriteLine(error);return 1;}finally{System.Windows.Application.Current?.Shutdown();}}
 static void Run(){
  var plugin=new BranchModulePlugin();var runtime=plugin.CreateRuntime();var parameters=plugin.Descriptor.Parameters.ToDictionary(p=>p.Name,p=>p.DefaultValue!.Value.Clone());parameters["ModuleInfoList"]=JsonSerializer.SerializeToElement("b#7$a#7$c#9$");
  ModuleResult Execute(int value,int mode=0){parameters["IndexUserSet"]=JsonSerializer.SerializeToElement(mode);return runtime.ExecuteAsync(new("branch",Environment.CurrentDirectory,new Dictionary<string,PortValue>{{"inputint",PortValue.Integer(value)}},parameters){ExecutionSuccessors=[new("a",101),new("b",102),new("c",103)]},default).Result;}
  var matching=Execute(7);Check(matching.SelectedExecutionSuccessors!.SequenceEqual(new[]{"b","a"}),"source row ordering controls route order");Check(matching.Outputs["BranchMatch"].As<string>()=="ID102;ID101;","mapped numeric IDs use original formatting");Check(matching.Outputs["ModuStatus"].As<long>()==1,"matched status");
  var bit=Execute(5,1);Check(bit.SelectedExecutionSuccessors!.SequenceEqual(new[]{"b","c"}),"bit selection uses row position rather than configured value");
  var none=Execute(99);Check(none.SelectedExecutionSuccessors!.Count==0&&none.Outputs["BranchMatch"].As<string>()=="No Module","no match explicitly suppresses all successors");Check(Execute(7,2).SelectedExecutionSuccessors!.Count==0,"unknown mode matches neither branch");
  var independent=runtime.ExecuteAsync(new("branch",Environment.CurrentDirectory,new Dictionary<string,PortValue>{{"inputint",PortValue.Integer(7)}},parameters){ExecutionSuccessors=[new("a")]},default).Result;
  parameters["IndexUserSet"]=JsonSerializer.SerializeToElement(0);independent=runtime.ExecuteAsync(new("branch",Environment.CurrentDirectory,new Dictionary<string,PortValue>{{"inputint",PortValue.Integer(7)}},parameters){ExecutionSuccessors=[new("a")]},default).Result;Check(independent.Outputs["BranchMatch"].As<string>()=="NodeId:a;"&&independent.Message!.Contains("Independent"),"unmapped identity is explicitly independent");
  var failure=runtime.ExecuteAsync(new("branch",Environment.CurrentDirectory,new Dictionary<string,PortValue>(),parameters){ReadIntegerInput=(_,_)=>new(0xe0000314,0,0)},default).Result;Check(failure.NativeErrorCode==0xe0000314&&failure.Outputs.Count==0&&failure.SelectedExecutionSuccessors!.Count==0,"read failure returns original error and clears route without outputs");
  var empty=runtime.ExecuteAsync(new("branch",Environment.CurrentDirectory,new Dictionary<string,PortValue>(),parameters){ReadIntegerInput=(_,_)=>new(0,0,0)},default).Result;Check(empty.Status==ModuleStatus.Success&&empty.Outputs.Count==0&&empty.SelectedExecutionSuccessors!.Count==0,"explicit successful zero-count provider preserves native early return");
  using(var scope=new ModuleExecutionScope()){var reader=new Reader();scope.RegisterService<IToolIntegerInputReader>(reader);var scoped=runtime.ExecuteAsync(new("branch",Environment.CurrentDirectory,new Dictionary<string,PortValue>{{"inputint",PortValue.Integer(99)}},parameters){Scope=scope.ForProcedure("p"),ExecutionSuccessors=[new("a",101)],ReadIntegerInput=(_,_)=>throw new Exception("scope reader must take precedence")},default).Result;Check(reader.Calls==1&&scoped.SelectedExecutionSuccessors!.SequenceEqual(new[]{"a"}),"scope integer reader wins over callback and materialized payload, index zero exactly once");}
  var unchanged=BranchRouteTable.ApplyTopologyChange([], [new("a")],[new("a")]);Check(unchanged.Rows.Count==0,"opening/restoring identical topology never repopulates reset table");var changed=BranchRouteTable.ApplyTopologyChange([new("b",7),new("a",4)],[new("a"),new("b")],[new("a"),new("c")]);Check(changed.Rows.SequenceEqual(new[]{new BranchStoredRoute("a",4),new BranchStoredRoute("c",0)}),"real topology mutation retains values/order and appends zero default");
  var topologyNode=new NodeDocument("branch",BranchModulePlugin.Id,"1.0.0","Branch",parameters);
  Check(ReferenceEquals(plugin.ApplyExecutionTopologyChange(topologyNode,[new("a")],[new("a")]),topologyNode),"topology identity no-op preserves original node including reset empty state");
  var edited=plugin.ApplyExecutionTopologyChange(topologyNode,[new("a"),new("b"),new("c")],[new("a",101),new("d",104)]);Check(edited.Parameters["ModuleInfoList"].GetString()=="a#7$d#0$","plugin topology seam retains eligible survivors and appends default");
  var thirtyTwo=Enumerable.Range(0,32).Select(i=>new ExecutionSuccessor("target"+i)).ToArray();bool cap=false;try{plugin.ApplyExecutionTopologyChange(topologyNode,thirtyTwo,thirtyTwo.Append(new ExecutionSuccessor("target32")).ToArray());}catch(InvalidOperationException){cap=true;}Check(cap,"source 32-connection gate rejects only further addition");Check(plugin.ApplyExecutionTopologyChange(topologyNode,thirtyTwo.Append(new ExecutionSuccessor("target32")).ToArray(),thirtyTwo).Parameters["ModuleInfoList"].GetString()!.Split('$',StringSplitOptions.RemoveEmptyEntries).Length==32,"removal from externally oversized document is not blocked");
  var copied=topologyNode with{Id="copy"};var copiedResult=plugin.PrepareCopiedNode(topologyNode,copied,new Dictionary<string,string>{{"a","a-copy"},{"c","c-copy"}},[new("a-copy"),new("c-copy")]);Check(copiedResult.Parameters["ModuleInfoList"].GetString()=="a-copy#7$c-copy#9$","copy plugin seam remaps only copied targets in source row order");
  Check(plugin.PrepareCopiedNode(topologyNode,copied,new Dictionary<string,string>(),[]).Parameters["ModuleInfoList"].GetString()=="","single-node copy has no stale target IDs after original ModuleOperate seed");
  Check(plugin.PrepareCopiedNode(topologyNode,copied,new Dictionary<string,string>(),[new("fresh")]).Parameters["ModuleInfoList"].GetString()=="fresh#0$","no mapped rows preserves topology seed rather than clearing it after Paste");
  Check(BranchCopyRows.Remap("a#N$b#-2$tail#9",new Dictionary<string,string>{{"a","A"},{"b","B"},{"tail","T"}})=="A#N$B#-2$","copy retains raw N/value text and ignores unterminated final row");
  int applies=0,runs=0;var node=new NodeDocument("branch",BranchModulePlugin.Id,"1.0.0","Branch",parameters);var editor=new ToolEditorContext(node,Environment.CurrentDirectory,next=>{parameters=next;applies++;},_=>{runs++;return Task.FromResult(new NodeRunRecord("branch",NodeRunStatus.Success,new Dictionary<string,PortValue>(),0));});
  using(var configuration=plugin.CreateConfiguration(editor)){
   Check(configuration.State.Find("ModuleInfoList")!.Value=="b#7$a#7$c#9$","configuration reads stored table without topology rebuild");
   Check(configuration.State.Find("ValueIndexHead")!.Visible&&!configuration.State.Find("BitIndexHead")!.Visible,"source value-mode header initialization");
   configuration.State.CommitUser("IndexUserSet","1");Check(parameters["IndexUserSet"].GetInt32()==1&&applies==1&&runs==0,"radio writes backend without PreRun");
   Check(!configuration.State.Find("ValueIndexHead")!.Visible&&configuration.State.Find("BitIndexHead")!.Visible,"source bit-mode triggers update both headers");
   configuration.State.CommitUser("ModuleInfoList","c#N$b#N$a#N$");Check(applies==2&&runs==0&&parameters["ModuleInfoList"].GetString()=="c#0$b#0$a#0$"&&configuration.State.Find("ModuleInfoList")!.Value=="c#N$b#N$a#N$","list change canonicalizes backend atoi while retaining attempted UI N without self-run");
   Check(!configuration.State.Nodes.Any(n=>n.Element.Tag=="ResetAlgorithmButton"),"no invented reset control");
   using var view=new ToolConfigurationView(configuration.State,configuration.Controls,configuration.Language,configuration.Localize);view.Measure(new System.Windows.Size(380,420));view.Arrange(new System.Windows.Rect(0,0,380,420));Check(view.Diagnostics.Count==0,"all original Branch leaf templates registered in actual common WPF view: "+string.Join(";",view.Diagnostics.Select(d=>d.Code+":"+d.TemplateKey+":"+d.Node+":"+d.Message)));Check(view.DesiredConfigurationSize.Width==420&&view.DesiredConfigurationSize.Height==420,"original Chinese host overrides CustomTabWidth with default CustomTabCHWidth420");
  }
  var registry=new ModuleRegistry();registry.Register(plugin.Descriptor,plugin.CreateRuntime);var sinkDescriptor=new ModuleDescriptor("test.branch-sink","1","Sink",[],[],[]);registry.Register(sinkDescriptor,()=>new Sink(sinkDescriptor));
  var branchParams=plugin.Descriptor.Parameters.ToDictionary(p=>p.Name,p=>p.DefaultValue!.Value.Clone());branchParams["ModuleInfoList"]=JsonSerializer.SerializeToElement("left#7$right#9$");var graphBranch=new NodeDocument("branch",BranchModulePlugin.Id,"1.0.0","Branch",branchParams);var graph=new ProcedureDocument("branch-graph","Branch",[graphBranch,new("left",sinkDescriptor.Id,"1","Left",new Dictionary<string,JsonElement>()),new("right",sinkDescriptor.Id,"1","Right",new Dictionary<string,JsonElement>())],[],[new("branch","left"),new("branch","right")]);
  Check(plugin.Descriptor.Outputs.Where(p=>p.Name!="ModuRunTime").All(p=>!p.CanSubscribe)&&plugin.Descriptor.Outputs.Single(p=>p.Name=="ModuRunTime").CanSubscribe,"source XML three forbidden outputs declared while runtime default stays allowed");
  var consumerDescriptor=new ModuleDescriptor("test.branch-subscriber","1","Subscriber",[new PortDescriptor("Value",DataKind.Integer,false)],[],[]);registry.Register(consumerDescriptor,()=>new Sink(consumerDescriptor));var subscriber=new NodeDocument("subscriber",consumerDescriptor.Id,"1","Subscriber",new Dictionary<string,JsonElement>());var subscriptionGraph=graph with{Nodes=graph.Nodes.Append(subscriber).ToArray(),ExecutionLinks=graph.ExecutionLinks!.Append(new("left","subscriber")).ToArray()};var service=new WorkflowConfigurationSubscriptionService(()=>subscriptionGraph,registry,"subscriber",(_,_)=>throw new Exception("forbidden binding cannot apply"));var query=new ConfigurationSubscriptionQuery(new(ConfigurationSubscriptionDomain.InputIo,"Value","int"),["int"]);var tree=service.Enumerate(query);Check(tree.Status==ConfigurationSubscriptionStatus.Available&&!tree.Roots.SelectMany(n=>n.Children).Any(n=>n.Binding?.Reference is ConfigurationOutputReference r&&r.NodeId=="branch"),"actual source subscription tree excludes Branch forbidden integer outputs");var rejected=service.Bind(query.Destination,new(new ConfigurationOutputReference(subscriptionGraph.Id,"branch","outputint","int"),ConfigurationSubscriptionIndex.All));Check(rejected.Status!=ConfigurationSubscriptionStatus.Available,"forged hidden Branch output binding rejected before host apply");
  using(var graphScope=new ModuleExecutionScope()){graphScope.RegisterService<IToolIntegerInputReader>(new Reader());var result=new GraphExecutor(registry).RunAsync(graph,Environment.CurrentDirectory,scope:graphScope.ForProcedure(graph.Id)).GetAwaiter().GetResult();Check(result.Nodes.Single(n=>n.NodeId=="branch").Status==NodeRunStatus.Success&&result.Nodes.Single(n=>n.NodeId=="left").Status==NodeRunStatus.Success&&result.Nodes.Single(n=>n.NodeId=="right").Status==NodeRunStatus.Skipped,"actual production Branch routes real Graph and suppresses unselected successor");var self=new GraphExecutor(registry).RunAsync(graph with{Nodes=[graphBranch],ExecutionLinks=[]},Environment.CurrentDirectory,scope:graphScope.ForProcedure(graph.Id),executionSuccessorRead:_=>[new("left"),new("right")]).GetAwaiter().GetResult();Check(self.Nodes.Count==1&&self.Nodes[0].Status==NodeRunStatus.Success&&self.Nodes[0].Outputs["BranchMatch"].As<string>()=="NodeId:left;","isolated production self-run observes real topology without executing absent nodes");}
  void ModeLifecycle(bool reopen){
   var saved=plugin.Descriptor.Parameters.ToDictionary(p=>p.Name,p=>p.DefaultValue!.Value.Clone());saved["ModuleInfoList"]=JsonSerializer.SerializeToElement("a#7$b#-2$");var applied=new List<(int Mode,string Rows)>();int invoked=0;var edit=new ToolEditorContext(new("mode",BranchModulePlugin.Id,"1.0.0","Mode",saved),Environment.CurrentDirectory,next=>{saved=next;applied.Add((saved["IndexUserSet"].GetInt32(),saved["ModuleInfoList"].GetString()!));},_=>{invoked++;throw new Exception("no implicit run");});
   ToolConfigurationSession open()=>plugin.CreateConfiguration(edit with{Node=edit.Node with{Parameters=saved}});
   using var initial=open();using var initialView=new ToolConfigurationView(initial.State,initial.Controls,initial.Language,initial.Localize);Layout(initialView);
   Radio(initialView,"按位索引").IsChecked=true;Check(saved["IndexUserSet"].GetInt32()==1&&saved["ModuleInfoList"].GetString()=="a#7$b#-2$","bit switch alone does not overwrite backend row values");
   var down=Walk(initialView).OfType<System.Windows.Controls.Button>().First(b=>b.IsEnabled&&b.Content is System.Windows.Controls.Image image&&image.Source.ToString()!.Contains("down-"));down.RaiseEvent(new System.Windows.RoutedEventArgs(System.Windows.Controls.Button.ClickEvent));Check(saved["ModuleInfoList"].GetString()=="b#0$a#0$"&&initial.State.Find("ModuleInfoList")!.Value=="b#N$a#N$","actual bit reorder writes native atoi0 while editor retains N");
   if(reopen){initial.Dispose();using var reopened=open();using var view=new ToolConfigurationView(reopened.State,reopened.Controls,reopened.Language,reopened.Localize);Layout(view);Radio(view,"按值索引").IsChecked=true;Check(saved["ModuleInfoList"].GetString()=="b#0$a#0$","reopened bit editor restores backend zeros instead of stale value memo");}
   else {int start=applied.Count;Radio(initialView,"按值索引").IsChecked=true;Check(saved["ModuleInfoList"].GetString()=="b#-2$a#7$","same editor restores original per-row memo after bit reorder");Check(applied.Skip(start).SequenceEqual(new[]{(1,"b#-2$a#0$"),(1,"b#-2$a#7$"),(0,"b#-2$a#7$")}),"source per-row TextChanged writes precede IndexUserSet backend write");}
   Check(invoked==0,"mode and reorder have no PreRun");
  }
  ModeLifecycle(false);ModeLifecycle(true);
  var model=new BranchModuleListModel();model.Read("a#7$b#-2$");model.SetMode(1);Check(model.Serialize()=="a#N$b#N$"&&!model.Rows[0].Enabled,"bit mode displays defaults and disables values");model.Move(1,-1);model.SetMode(0);Check(model.Serialize()=="b#-2$a#7$","mode switch and reorder preserve per-row memo");
 }
 sealed class Reader:IToolIntegerInputReader{public int Calls;public ToolIntegerInputReadResult Read(ModuleExecutionContext context,string name,int index){if(name!="inputint"||index!=0)throw new Exception("wrong integer leaf/index");Calls++;return new(0,3,7);}}
 sealed class Sink(ModuleDescriptor descriptor):IModule{public ModuleDescriptor Descriptor=>descriptor;public ValueTask<ModuleResult> ExecuteAsync(ModuleExecutionContext context,CancellationToken cancellationToken)=>ValueTask.FromResult(new ModuleResult(ModuleStatus.Success,new Dictionary<string,PortValue>()));}
 static IEnumerable<System.Windows.DependencyObject> Walk(System.Windows.DependencyObject value){yield return value;for(int i=0;i<System.Windows.Media.VisualTreeHelper.GetChildrenCount(value);i++)foreach(var child in Walk(System.Windows.Media.VisualTreeHelper.GetChild(value,i)))yield return child;}
 static void Layout(ToolConfigurationView view){view.Measure(new System.Windows.Size(420,420));view.Arrange(new System.Windows.Rect(0,0,420,420));view.UpdateLayout();}
 static System.Windows.Controls.RadioButton Radio(ToolConfigurationView view,string text)=>Walk(view).OfType<System.Windows.Controls.RadioButton>().Single(r=>Equals(r.Content,text));
}











